struct RingBuffer {
    RingBuffer(int capacity) : cap(capacity), head(0), count(0) {
        // cap is guaranteed >= 1 by contract
    }

    bool push(int value) {
        if (full()) return false;
        data[(head + count) % cap] = value;
        ++count;
        return true;
    }

    bool pop(int& out) {
        if (empty()) return false;
        out = data[head];
        head = (head + 1) % cap;
        --count;
        return true;
    }

    int size() const { return count; }
    bool empty() const { return count == 0; }
    bool full() const { return count == cap; }

private:
    int data[1024];
    int cap;
    int head;   // index of oldest element
    int count;  // number of stored elements
};
```

**Notes on correctness:**

- **FIFO order:** `head` always points at the oldest element; `push` writes at `(head + count) % cap`, so the newest element goes right after the oldest ones, wrapping modulo the capacity.
- **Wrap-around:** Both indices are advanced with `% cap`, so after filling and draining repeatedly the indices keep cycling through `[0, cap)` without ever going out of bounds.
- **Full push:** `full()` is checked first; on `false` return, neither `data`, `head`, nor `count` are modified, so no data is lost or overwritten.
- **Empty pop:** `empty()` is checked first; `out` is only assigned after the check, so it is untouched on failure.
- **Fixed capacity:** The backing store is a plain `int[1024]`, and only the first `cap` slots are ever used.

